{
  "name": "SmartVoiceX",
  "version": "1.0.9",
  "description": "AI Agent Control Panel",
  "main": "main.js",
  "scripts": {
    "start": "electron .",
    "pack": "electron-builder --dir",
    "dist": "electron-builder",
    "build": "electron-builder",
    "publish": "electron-builder --win --publish always",
    "newver": "electron-builder -- --publish always"
  },
  "build": {
    "appId": "com.keithazodeh.smartvoicex",
    "productName": "SmartVoiceX",
    "win": {
      "target": "nsis",
      "icon": "build/logo.ico"
    },
    "nsis": {
      "oneClick": true,
      "perMachine": false,
      "allowElevation": false,
      "allowToChangeInstallationDirectory": false,
      "deleteAppDataOnUninstall": false
    },
    "extraResources": [
      {
        "from": "k",
        "to": "k"
      }
    ],
    "publish": [
      {
        "provider": "github",
        "owner": "yadasa",
        "repo": "dentai",
        "private": true
      }
    ]
  },
  "dependencies": {
    "axios": "^1.13.2",
    "dotenv": "^17.2.3",
    "electron-store": "^8.2.0",
    "electron-updater": "^6.0.0",
    "googleapis": "^166.0.0",
    "twilio": "^5.2.0",
    "ws": "^8.18.3"
  },
  "devDependencies": {
    "electron": "^30.0.0",
    "electron-builder": "^24.0.0"
  }
}
